# 1. LastValue: 单值覆盖通道（同超步禁止并发双写）
class LastValue(BaseChannel):
    def update(self, values: Sequence[Value]) -> bool:
        if len(values) > 1: raise InvalidUpdateError('Concurrent write!')
        self.value = values[-1]; return True

# 2. BinaryOperatorAggregate: 二元归约通道 (Annotated[list, operator.add])
class BinaryOperatorAggregate(BaseChannel):
    def update(self, values: Sequence[Value]) -> bool:
        for v in values: self.value = self.operator(self.value, v)
        return True

# 3. NamedBarrierValue: 扇入同步屏障 (集齐所有前置节点才放行)
class NamedBarrierValue(BaseChannel):
    def update(self, values: Sequence[str]) -> bool:
        self.seen.update(values)  # 当 self.seen == self.names 时变为可读!
    def consume(self) -> bool:
        if self.seen == self.names: self.seen.clear(); return True

