def prepare_next_tasks(checkpoint, processes, channels, updated_channels):
    tasks = []
    # 1. PUSH 通道：消费 __pregel_tasks (Topic) 中动态投递的 Send 任务包
    for idx, packet in enumerate(channels[TASKS].get_if_available()):
        tasks.append(prepare_push_task_send(idx, packet, channels))
    # 2. PULL 通道：仅唤醒存在 channel_versions[c] > versions_seen[node][c] 的节点
    for name, proc in processes.items():
        if any(channels[c].is_available() and versions[c] > seen[name].get(c, 0)
               for c in proc.triggers):
            private_input = _proc_input(proc, channels)  # 拷贝只读快照，隔离并发读写
            tasks.append(PregelExecutableTask(name, private_input, proc, deque()))
    return tasks

def apply_writes(checkpoint, channels, tasks, get_next_version):
    # 超步同步屏障：统一记录 versions_seen -> 消费屏障通道 -> 批量 update 并递增版本号
    for t in tasks:
        for ch in t.triggers: checkpoint['versions_seen'][t.name][ch] = checkpoint['channel_versions'][ch]
    next_ver = get_next_version(max(checkpoint['channel_versions'].values(), default=0))
    for ch, vals in group_writes_by_channel(tasks).items():
        if channels[ch].update(vals): checkpoint['channel_versions'][ch] = next_ver

